package au.aumanet.app;

import org.json.*;
import java.nio.file.*;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.io.IOException;
import java.util.concurrent.atomic.AtomicInteger;

/** Host-only real JSON/filesystem fault tests. No Android identities or transport fixtures. */
public final class GroupNamesTest {
    static int assertions,tests;
    interface Work {void run()throws Exception;}
    static void check(boolean value){assertions++;if(!value)throw new AssertionError("Name policy assertion failed");}
    static void rejects(Work work)throws Exception{assertions++;try{work.run();throw new AssertionError("Expected rejection");}catch(AssertionError wrong){throw wrong;}catch(Exception expected){}}
    static JSONObject receipt(int id,long revision)throws Exception{return new JSONObject().put("operationId",String.format("%032x",id)).put("processId","12345678-1234-1234-1234-123456789abc").put("selfId","AA".repeat(32)).put("kind","self").put("name","Person "+id).put("groupId","a".repeat(32)).put("epoch",3).put("expectedRevision",revision).put("revision",revision+1);}
    static void commit(Path file,JSONArray value)throws Exception{Path next=file.resolveSibling(file.getFileName()+".pending");byte[] bytes=value.toString().getBytes(StandardCharsets.UTF_8);try(FileChannel out=FileChannel.open(next,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE)){out.write(java.nio.ByteBuffer.wrap(bytes));out.force(true);}Files.move(next,file,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
    static GroupNameJournal open(Path file)throws Exception{return new GroupNameJournal(Files.exists(file)?Files.readString(file):"[]");}
    static JSONObject profile(long generation)throws Exception{return new JSONObject().put("self","AA".repeat(32)).put("name","Verified person").put("revision",4).put("nameGeneration",generation);}
    static JSONObject membership(long generation)throws Exception{return new JSONObject().put("self","AA".repeat(32)).put("name","Verified person").put("selfNameRevision",4).put("nameGeneration",generation).put("groupId","a".repeat(32)).put("groupName","Verified group").put("groupNameRevision",7).put("owner","AA".repeat(32)).put("role","owner").put("epoch",3).put("host","192.168.0.10").put("port",12345).put("members",new JSONArray().put(new JSONObject().put("id","AA".repeat(32)).put("name","Verified person").put("nameRevision",4)));}
    static GroupNameRepair.Scope scope(long generation,long run){return new GroupNameRepair.Scope("p","self","g",3,4,7,generation,run);}
    public static void main(String[] args)throws Exception{
        Path root=Path.of(args[0]);Files.createDirectories(root);
        tests++;check(GroupNamePolicy.label(" \ufeffCafe\u0301 ",48).equals("Café"));
        for(int max:new int[]{48,64}){String text="😀".repeat(max);check(GroupNamePolicy.label(text,max).equals(text));check(GroupNamePolicy.label(new JSONObject().put("name",text).toString().isEmpty()?"":new JSONObject(new JSONObject().put("name",text).toString()).getString("name"),max).equals(text));rejects(()->GroupNamePolicy.label(text+"😀",max));}
        for(String bad:new String[]{"","A\u0085B","A\u202eB","\u001cPerson","A\ud800B","A\udfffB"})rejects(()->GroupNamePolicy.label(bad,48));
        tests++;GroupNamePolicy.scope("p","p","g","g",3,3,4,4);for(int n=0;n<4;n++){final int fault=n;rejects(()->GroupNamePolicy.scope(fault==0?"x":"p","p",fault==1?"x":"g","g",fault==2?2:3,3,fault==3?2:4,4));}GroupNamePolicy.owner(true,true);rejects(()->GroupNamePolicy.owner(false,true));rejects(()->GroupNamePolicy.owner(true,false));rejects(()->GroupNamePolicy.next(GroupNamePolicy.MAX_REVISION));
        tests++;Path durable=root.resolve("durable.json");GroupNameJournal first=open(durable);JSONObject edit=receipt(1,0);AtomicInteger writes=new AtomicInteger();first.commit(edit,candidate->{writes.incrementAndGet();commit(durable,candidate);});check(writes.get()==1);GroupNameJournal reopened=open(durable);check(reopened.same(edit,reopened.find(edit.getString("operationId"))));reopened.commit(edit,candidate->{throw new AssertionError("Duplicate operation wrote again");});JSONObject collision=new JSONObject(edit.toString()).put("name","Different");rejects(()->reopened.commit(collision,candidate->{throw new AssertionError("Conflicting operation wrote");}));check(reopened.healthy());
        tests++;Path before=root.resolve("before.json");GroupNameJournal pre=open(before);try{pre.commit(receipt(2,0),candidate->{throw new IOException("PRIVATE-SENTINEL-name");});throw new AssertionError();}catch(GroupNameJournal.Uncertain uncertain){check(!uncertain.getMessage().contains("PRIVATE-SENTINEL"));}check(!pre.healthy());rejects(()->pre.find(String.format("%032x",2)));rejects(()->pre.commit(receipt(3,0),candidate->{throw new AssertionError("Poisoned journal wrote");}));check(open(before).find(String.format("%032x",2))==null);
        tests++;Path after=root.resolve("after.json");GroupNameJournal post=open(after);JSONObject accepted=receipt(4,0);rejects(()->post.commit(accepted,candidate->{commit(after,candidate);throw new IOException("Reply lost after durable write");}));rejects(()->post.find(accepted.getString("operationId")));GroupNameJournal afterRestart=open(after);check(afterRestart.same(accepted,afterRestart.find(accepted.getString("operationId"))));afterRestart.commit(accepted,candidate->{throw new AssertionError("Recovery resent edit");});
        tests++;Path cap=root.resolve("cap.json");GroupNameJournal bounded=open(cap);for(int id=1;id<=17;id++){final int next=id;bounded.commit(receipt(next,next-1),candidate->commit(cap,candidate));}check(new JSONArray(Files.readString(cap)).length()==16);check(bounded.find(String.format("%032x",1))==null);check(bounded.find(String.format("%032x",17))!=null);rejects(()->GroupNamePolicy.scope("p","p","g","g",3,3,0,17));
        tests++;GroupNamePolicy.profile(2,"Current",2,"Current");GroupNamePolicy.profile(2,"Current",3,"Next");rejects(()->GroupNamePolicy.profile(2,"Current",1,"Previous"));rejects(()->GroupNamePolicy.profile(2,"Current",2,"Conflicting"));
        tests++;rejects(()->new GroupNameJournal(new JSONArray().put(receipt(1,0)).put(receipt(1,0)).toString()));rejects(()->GroupNameJournal.validate(receipt(1,0).put("revision",1.5)));rejects(()->new GroupNameJournal("[PRIVATE-SENTINEL"));
        for(JSONObject bad:new JSONObject[]{receipt(1,0).put("unknown","PRIVATE-SENTINEL"),receipt(1,0).put("processId","-".repeat(36)),receipt(1,0).put("name"," Person "),receipt(1,0).put("name","Cafe\u0301"),receipt(1,0).put("groupId",""),receipt(1,0).put("epoch",0),receipt(1,0).put("kind","other"),receipt(1,0).put("epoch","3")})rejects(()->new GroupNameJournal(new JSONArray().put(bad).toString()));
        rejects(()->new GroupNameJournal(" ".repeat(32769)));rejects(()->new GroupNameJournal("😀".repeat(10000)));
        tests++;GroupNameJournal crashed=new GroupNameJournal("[]");try{crashed.commit(receipt(99,0),candidate->{throw new AssertionError("storage interrupted");});throw new IllegalStateException("Expected Error");}catch(AssertionError expected){}check(!crashed.healthy());rejects(()->crashed.find(String.format("%032x",99)));
        tests++;for(String invalid:new String[]{"[] junk","[] {}","[];","[1,]","[{'a':1}]","[{unquoted:1}]","[01]","[+1]","[NaN]","[{\"a\":1,\"a\":2}]","[\"\\uFF０0\"]"})rejects(()->GroupNameJson.read(invalid,32768));check(GroupNameJson.read(" \n[1, {\"literal\":\"\\u0061\",\"array\":[true,false,null,-1.25e+2]}]\t",32768) instanceof JSONArray);rejects(()->new GroupNameJournal("[] trailing"));
        tests++;String legacy=new JSONArray().put(receipt(5,0)).toString();check(new GroupNameJournal(legacy,0).find(String.format("%032x",5))!=null);rejects(()->new GroupNameJournal(legacy,1));GroupNameJournal retired=new GroupNameJournal("[]",1);rejects(()->retired.commit(receipt(6,0),candidate->{throw new AssertionError("Old generation wrote");}));retired.commit(receipt(6,0).put("generation",1),candidate->{});check(retired.find(String.format("%032x",6)).getLong("generation")==1);rejects(()->new GroupNameJournal(new JSONArray().put(receipt(6,0).put("generation",1)).toString(),2));
        tests++;JSONObject profile=profile(0),membership=membership(0);GroupNameMetadata.Trusted trust=GroupNameMetadata.read("AA".repeat(32),profile.toString(),membership.toString());check(trust.name.equals("Verified person")&&trust.groupName.equals("Verified group")&&trust.selfRevision==4&&trust.groupRevision==7&&trust.generation==0);check(GroupNameMetadata.read("AA".repeat(32),profile.toString(),"").groupId.isEmpty());
        check(GroupNameMetadata.read("AA".repeat(32),profile.toString(),membership(0).put("offlineRequestHash","AB".repeat(32)).put("offlineApproval","aumanet://approval/fixture").toString()).epoch==3);
        rejects(()->GroupNameMetadata.read("AA".repeat(32),profile.toString(),membership(0).put("offlineRequestHash","AB".repeat(32)).toString()));
        rejects(()->GroupNameMetadata.read("AA".repeat(32),profile.toString(),membership(0).put("offlineRequestHash",true).put("offlineApproval","aumanet://approval/fixture").toString()));
        for(JSONObject invalid:new JSONObject[]{membership(0).put("name","Other person"),membership(0).put("selfNameRevision",5),membership(1),membership(0).put("groupName"," Noncanonical "),membership(0).put("epoch","3"),membership(0).put("members",new JSONArray()),membership(0).put("self","BB".repeat(32)),membership(0).put("port",1.5),membership(0).put("host","8.8.8.8"),membership(0).put("unknownCredential",true),membership(0).put("groupName",123),membership(0).put("name",123)})rejects(()->GroupNameMetadata.read("AA".repeat(32),profile.toString(),invalid.toString()));
        rejects(()->GroupNameMetadata.read("AA".repeat(32),profile.toString()+" junk",membership.toString()));rejects(()->GroupNameMetadata.read("AA".repeat(32),profile(0).put("unknown",true).toString(),membership.toString()));rejects(()->GroupNameMetadata.read("AA".repeat(32),"",membership.toString()));check(GroupNameMetadata.read("AA".repeat(32),profile(1).toString(),membership(1).toString()).generation==1);
        tests++;String token="b".repeat(64);GroupNameRepair repair=new GroupNameRepair();GroupNameRepair.Scope expected=scope(0,9);repair.prepare(expected,expected,token,100);check(repair.consume(expected,expected,token,29999)==1);rejects(()->repair.consume(expected,expected,token,29999));repair.prepare(expected,expected,token,100);rejects(()->repair.consume(expected,expected,token,30100));repair.prepare(expected,expected,token,100);rejects(()->repair.consume(expected,scope(0,10),token,101));repair.prepare(expected,expected,token,100);rejects(()->repair.consume(expected,expected,"c".repeat(64),101));rejects(()->repair.consume(expected,expected,token,102));rejects(()->repair.prepare(scope(GroupNamePolicy.MAX_REVISION,9),scope(GroupNamePolicy.MAX_REVISION,9),token,100));
        for(GroupNameRepair.Scope changed:new GroupNameRepair.Scope[]{new GroupNameRepair.Scope("other","self","g",3,4,7,0,9),new GroupNameRepair.Scope("p","other","g",3,4,7,0,9),new GroupNameRepair.Scope("p","self","other",3,4,7,0,9),new GroupNameRepair.Scope("p","self","g",4,4,7,0,9),new GroupNameRepair.Scope("p","self","g",3,5,7,0,9),new GroupNameRepair.Scope("p","self","g",3,4,8,0,9),scope(1,9)}){repair.prepare(expected,expected,token,100);rejects(()->repair.consume(changed,expected,token,101));}
        tests++;GroupNameJournal corrupt=new GroupNameJournal("[]",0);corrupt.unavailable();Path repaired=root.resolve("repair.json");rejects(()->GroupNameRepair.replace(corrupt,0,()->{throw new AssertionError("Generation did not advance");}));GroupNameJournal fresh=GroupNameRepair.replace(corrupt,1,()->commit(repaired,new JSONArray().put(new JSONObject().put("profile",profile(1)).put("membership",membership(1)).put("journal",new JSONArray()))));check(fresh.healthy());check(profile(1).getString("name").equals(profile.getString("name")));check(membership(1).getLong("groupNameRevision")==membership.getLong("groupNameRevision"));rejects(()->fresh.commit(receipt(9,0),candidate->{throw new AssertionError("Retired old edit applied");}));
        GroupNameJournal interrupted=new GroupNameJournal("[]",0);interrupted.unavailable();rejects(()->GroupNameRepair.replace(interrupted,1,()->{throw new IOException("Before commit");}));check(interrupted.uncertain());rejects(()->interrupted.find(String.format("%032x",9)));
        GroupNameJournal committedUnknown=new GroupNameJournal("[]",0);committedUnknown.unavailable();rejects(()->GroupNameRepair.replace(committedUnknown,1,()->{commit(repaired,new JSONArray().put(new JSONObject().put("profile",profile(1)).put("membership",membership(1)).put("journal",new JSONArray())));throw new IOException("After commit");}));check(committedUnknown.uncertain());JSONObject disk=new JSONArray(Files.readString(repaired)).getJSONObject(0);GroupNameMetadata.Trusted reopenedTrust=GroupNameMetadata.read("AA".repeat(32),disk.getJSONObject("profile").toString(),disk.getJSONObject("membership").toString());check(reopenedTrust.generation==1&&reopenedTrust.selfRevision==4&&reopenedTrust.groupRevision==7&&reopenedTrust.epoch==3);check(new GroupNameJournal(disk.getJSONArray("journal").toString(),reopenedTrust.generation).healthy());
        System.out.println(new JSONObject().put("status","passed").put("testCount",tests).put("assertionCount",assertions));
    }
}
